const auto move = study_collision::try_shift(candidate.board_,
                                             *candidate.active_, direction);
if (move == study_movement::Result::invalid) return Step::invalid;
if (move == study_movement::Result::moved) candidate.rotation_ready_ = false;
auto turn = study_rotation::Result::blocked; // No requested shape change.
if (clockwise) {
    const auto rotation = study_kicks::try_clockwise(candidate.board_,*candidate.active_,
                                                     candidate.kind_,candidate.quarter_);
    turn = rotation.result;
    candidate.last_rotation_candidate_ = rotation.candidate_index;
    if (turn == study_rotation::Result::invalid) return Step::invalid;
    if (turn == study_rotation::Result::rotated) candidate.rotation_ready_ = true;
}

// Project policy: hard drop preserves rotation eligibility, even with travel.
candidate.active_ = landing->piece;
candidate.last_hard_drop_distance_ = landing->distance;

if (fall == study_gravity::TickResult::invalid) return Step::invalid;
if (soft == study_movement::Result::moved || fall == study_gravity::TickResult::moved)
    candidate.rotation_ready_ = false;

inline std::optional<bool> classify(const study_grid::Grid& board,
                                    const study_piece::Piece& piece,
                                    study_catalog::Kind kind, int quarter,
                                    bool rotation_ready) noexcept {
    const auto shape = study_rotation::shape_at(kind,quarter);
    if (!shape || !study_rotation::same_cells(*shape,piece.local) ||
        study_collision::classify(board,piece) != study_collision::Placement::clear)
        return std::nullopt;
    if (kind != study_catalog::Kind::T || !rotation_ready) return false;
    // T's fixed local pivot is (1,1), not its current bounding-box center.
    // Widen before adding, even though the valid-pose contract bounds this origin.
    const std::int64_t pr = std::int64_t{piece.origin.row} + 1;
    const std::int64_t pc = std::int64_t{piece.origin.column} + 1;
    int blocked = 0;
    for (int dr : {-1,1}) for (int dc : {-1,1}) {
        const auto r=pr+dr,c=pc+dc;
        if (r<0 || r>=study_grid::Grid::kRows || c<0 || c>=study_grid::Grid::kColumns)
            ++blocked;
        else if (board.get(static_cast<int>(r),static_cast<int>(c)) == study_grid::Cell::filled)
            ++blocked;
    }
    return blocked >= 3;
}

const auto spin = study_spin::classify(candidate.board_,*candidate.active_,
                                       candidate.kind_,candidate.quarter_,candidate.rotation_ready_);
if (!spin) return Step::invalid;
if (study_locking::try_lock(candidate.board_, *candidate.active_) !=
    study_locking::Result::locked) return Step::invalid;
candidate.active_.reset(); // The locked piece now belongs to the board.
// Resolve the board before testing the next spawn.
candidate.last_cleared_ = study_lines::clear_full_rows(candidate.board_);
candidate.last_t_spin_lines_ = *spin ? candidate.last_cleared_ : -1;
const auto scored = study_score::award(candidate.totals_,candidate.last_cleared_,*spin);
if (!scored) return Step::invalid;

inline std::optional<std::uint64_t> spin_points(int rows, unsigned level) noexcept {
    if (rows < 0 || rows > 3 || level < 1 || level > 20) return std::nullopt;
    constexpr std::uint64_t table[] = {400,800,1200,1600};
    return table[rows] * level;
}

inline std::optional<Totals> award(const Totals& before, int rows, bool t_spin = false) noexcept {
    const auto points = t_spin ? spin_points(rows,level(before)) : normal_points(rows,level(before));
    if (!points) return std::nullopt;
    Totals after = before;
    after.points = saturating_add(before.points, *points);
    after.lines = saturating_add(before.lines, static_cast<std::uint64_t>(rows));
    return after;
}

inline int combo_bonus(std::uint64_t clears) noexcept {
    if (clears >= 9) return 4;
    if (clears == 0) return 0;
    return static_cast<int>((clears - 1) / 2);
}

inline std::optional<ClearReward> reward(Chain before,
                                         int rows,
                                         bool t_spin) noexcept {
    // Bounds: normal rows 0..4, spin rows 0..3; otherwise invalid.
    if (rows < 0) return std::nullopt;
    if (t_spin) {
        if (rows > 3) return std::nullopt;
    } else {
        if (rows > 4) return std::nullopt;
    }

    // AFTER streak: positive locks extend saturating, zero lines reset.
    Chain after;
    if (rows > 0) {
        after.clears = study_score::saturating_add(before.clears, static_cast<std::uint64_t>(1));
    } else {
        after.clears = 0;  // resets even for a T-spin 0
    }

    // Base attack from the variant table.
    static const int k_normal[5] = {0, 0, 1, 2, 4};
    static const int k_spin[4]   = {0, 2, 4, 6};
    const int base = t_spin ? k_spin[rows] : k_normal[rows];

    // Combo bonus only for clearing locks, based on the AFTER streak.
    const int bonus = (rows > 0) ? detail::combo_bonus(after.clears) : 0;

    ClearReward out;
    out.chain = after;
    out.attack = base + bonus;
    return out;
}

const auto reward = study_history::reward(candidate.chain_,candidate.last_cleared_,*spin);
if (!reward) return Step::invalid;
candidate.chain_ = reward->chain;
candidate.rotation_ready_ = false;
candidate.attack_sent_ = study_score::saturating_add(candidate.attack_sent_,
                                                   static_cast<std::uint64_t>(reward->attack));
